import moment from 'moment-timezone'
import dayjs from '/dayjs/src'
import utc from '/dayjs/src/plugin/utc'
import timezone from '/dayjs/src/plugin/timezone'

dayjs.extend(utc)
dayjs.extend(timezone)

const zones = ['America/Los_Angeles', 'America/New_York', 'Europe/London', 'Asia/Tokyo', 'Asia/Kathmandu', 'UTC', 'Australia/Sydney', 'Pacific/Auckland', 'Asia/Tehran', 'America/St_Johns', 'Pacific/Chatham', 'Asia/Kolkata']
const instants = []
for (let m = 0; m < 12; m += 1) {
  instants.push(new Date(Date.UTC(2014, m, 1, 12, 0, 0)).toISOString())
  instants.push(new Date(Date.UTC(2014, m, 15, 23, 30, 0)).toISOString())
}

it('brute', () => {
  const bad = []
  zones.forEach((z) => {
    instants.forEach((i) => {
      const dj = dayjs(i).tz(z)
      const mj = moment(i).tz(z)
      const checks = [
        ['format', dj.format(), mj.format()],
        ['Z', dj.format('Z'), mj.format('Z')],
        ['ZZ', dj.format('ZZ'), mj.format('ZZ')],
        ['offset', dj.utcOffset(), mj.utcOffset()],
        ['valueOf', dj.valueOf(), mj.valueOf()]
      ]
      checks.forEach(([n, a, b]) => {
        if (a !== b) bad.push(`${i} ${z} ${n}: dayjs=${a} moment=${b}`)
      })
      // chained
      const dj2 = dj.tz('Asia/Tokyo')
      const mj2 = mj.tz('Asia/Tokyo')
      if (dj2.format() !== mj2.format()) bad.push(`${i} ${z} -> Tokyo format: ${dj2.format()} vs ${mj2.format()}`)
      if (dj2.valueOf() !== mj2.valueOf()) bad.push(`${i} ${z} -> Tokyo valueOf: ${dj2.valueOf()} vs ${mj2.valueOf()}`)
    })
  })
  console.log('BAD COUNT', bad.length)
  bad.slice(0, 40).forEach(b => console.log('BAD', b))
})
